package com.shouxin.qa.qapair;
import com.shouxin.qa.auth.AuthUserService;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.FileSystemResource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
@RestController @RequestMapping("/api/qa-pairs/{pairId}/attachments") public class AttachmentController{private final JdbcTemplate jdbc;private final AuthUserService users;private final PairAccess access;private final Path root;public AttachmentController(JdbcTemplate j,AuthUserService u,PairAccess a,@Value("${app.storage.path}")String p){jdbc=j;users=u;access=a;root=Paths.get(p).toAbsolutePath().normalize();}
 @PostMapping @PreAuthorize("hasAnyRole('QA_SUBMITTER','QA_ADMIN','SYS_ADMIN')") public Map<String,Object> upload(@PathVariable String pairId,@RequestPart("file")MultipartFile file,Authentication authentication)throws IOException{access.require(pairId,authentication,true);if(file.isEmpty()||file.getSize()>50*1024*1024)throw new IllegalArgumentException("文件为空或超过50MB");String version=jdbc.queryForObject("SELECT current_version_id FROM qa_pair WHERE id=? AND deleted=0",String.class,pairId);if(version==null)throw new NoSuchElementException("问答对不存在");Files.createDirectories(root);String key=UUID.randomUUID()+"-"+Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"file")).getFileName();Path target=root.resolve(key).normalize();if(!target.startsWith(root))throw new IllegalArgumentException("非法文件名");Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);String checksum=sha256(target),id=UUID.randomUUID().toString();jdbc.update("INSERT INTO qa_attachment(id,version_id,original_name,object_key,content_type,size_bytes,checksum,created_by) VALUES(?,?,?,?,?,?,?,?)",id,version,file.getOriginalFilename(),key,file.getContentType(),file.getSize(),checksum,users.findByUsername(authentication.getName()).id());return Map.of("id",id,"name",file.getOriginalFilename(),"size",file.getSize(),"checksum",checksum);}
 @GetMapping @PreAuthorize("isAuthenticated()") public List<Map<String,Object>> list(@PathVariable String pairId,Authentication authentication){access.require(pairId,authentication,false);return jdbc.queryForList("SELECT a.id,a.original_name,a.content_type,a.size_bytes,a.checksum,a.created_at FROM qa_attachment a JOIN qa_pair_version v ON v.id=a.version_id WHERE v.qa_pair_id=? ORDER BY a.created_at DESC",pairId);}
 @GetMapping("/{id}/download") @PreAuthorize("isAuthenticated()") public FileSystemResource download(@PathVariable String pairId,@PathVariable String id,Authentication authentication){access.require(pairId,authentication,false);String key=jdbc.queryForObject("SELECT object_key FROM qa_attachment a JOIN qa_pair_version v ON v.id=a.version_id WHERE a.id=? AND v.qa_pair_id=?",String.class,id,pairId);Path target=root.resolve(key).normalize();if(!target.startsWith(root)||!Files.exists(target))throw new NoSuchElementException("附件不存在");return new FileSystemResource(target);}
 private String sha256(Path p)throws IOException{try{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(p)){byte[] b=new byte[8192];for(int n;(n=in.read(b))>0;)md.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format("%02x",b));return s.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
